func evMetaHash(s string) string { h := sha256.Sum256([]byte(s)); return hex.EncodeToString(h[:]) }
func evMetaJSON(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		panic(err)
	}
	return string(b)
}
func evMetaFields(t *testing.T, wire string) map[string]json.RawMessage {
	t.Helper()
	var m map[string]json.RawMessage
	if err := json.Unmarshal([]byte(wire), &m); err != nil {
		t.Fatal(err)
	}
	return m
}
func evMetaString(t *testing.T, m map[string]json.RawMessage, key string) string {
	t.Helper()
	var s string
	if err := json.Unmarshal(m[key], &s); err != nil {
		t.Fatal(key, err)
	}
	return s
}
func evMetaRehash(t *testing.T, wire string) string {
	t.Helper()
	m := evMetaFields(t, wire)
	old := evMetaString(t, m, "identity")
	unsigned := strings.Replace(wire, `,"identity":`+evMetaJSON(old), "", 1)
	domain := evMetaString(t, m, "contract") + "/v" + string(m["schema_version"]) + "\x00"
	return strings.Replace(wire, `"identity":`+evMetaJSON(old), `"identity":`+evMetaJSON(evMetaHash(domain+unsigned)), 1)
}
func evMetaChange(t *testing.T, wire string, changes map[string]string, rehash bool) string {
	t.Helper()
	m := evMetaFields(t, wire)
	for key, value := range changes {
		old, ok := m[key]
		if !ok {
			t.Fatal("missing fixture field", key)
		}
		wire = strings.Replace(wire, evMetaJSON(key)+":"+string(old), evMetaJSON(key)+":"+value, 1)
	}
	if rehash {
		wire = evMetaRehash(t, wire)
	}
	return wire
}
func evMetaNested(t *testing.T, outer, inner string) string {
	t.Helper()
	return evMetaChange(t, outer, map[string]string{"record_hex": evMetaJSON(hex.EncodeToString([]byte(inner)))}, true)
}
